import * as React from "react";
import {useEffect, useMemo, useRef, useState} from "react";
import {graphql, type HeadFC, type PageProps} from "gatsby";
import {Chart, registerables} from "chart.js";
import Header from "../components/Header";
import Footer from "../components/Footer";
import Ticker from "../components/Ticker";
import I18nText from "../components/I18nText";
import LangSwitcher from "../components/LangSwitcher";
import {asOfDate, type Lang, rankLabel, stockLabels} from "../i18n/stockLabels";
import {useAutoLang} from "../hooks/useAutoLang";

Chart.register(...registerables);

const RANK_COLORS = ["#2563eb", "#dc2626", "#16a34a", "#d97706", "#7c3aed", "#0891b2", "#db2777", "#65a30d"];

export const query = graphql`
  query($symbol: String!) {
    stockDetail(symbol: { eq: $symbol }) {
      symbol
      market
      stock_name
      growth
      dividend
      recent_price
      basis_date
      nps_holding
      overview
    }
    allShareholder(filter: { symbol: { eq: $symbol } }, sort: { date: DESC }) {
      nodes {
        id
        date
        holder_name
        value
      }
    }
    allInvestor(filter: { symbol: { eq: $symbol } }, sort: { base_date: ASC }) {
      nodes {
        id
        base_date
        investor_count
        avg_price
      }
    }
  }
`;

interface StockDetailData {
    symbol: string;
    market: string;
    stock_name: string;
    growth: number | null;
    dividend: number | null;
    recent_price: number | null;
    basis_date: string | null;
    nps_holding: boolean | null;
    overview: string | null;
}

interface InvestorNode {
    id: string;
    base_date: string;
    investor_count: number | null;
    avg_price: number | null;
}

interface ShareholderNode {
    id: string;
    date: string;
    holder_name: string;
    value: number;
}

interface DataProps {
    stockDetail: StockDetailData | null;
    allShareholder: { nodes: ShareholderNode[] };
    allInvestor: { nodes: InvestorNode[] };
}

const getCurrency = (market: string, lang: Lang) => {
    if (market === "KOSPI" || market === "KOSDAQ") return stockLabels.krw[lang];
    if (market === "TSE") return "¥";
    return "$";
};

const StockDetailPage: React.FC<PageProps<DataProps>> = ({data}) => {
    const stock = data.stockDetail;
    const shareholders = data.allShareholder.nodes;
    const investors = data.allInvestor.nodes;

    const [lang, setLang] = useAutoLang();
    const [isDark, setIsDark] = useState(false);
    useEffect(() => {
        const updateIsDark = () => setIsDark(document.documentElement.classList.contains("dark"));
        updateIsDark();

        const observer = new MutationObserver(updateIsDark);
        observer.observe(document.documentElement, {attributes: true, attributeFilter: ["class"]});
        return () => observer.disconnect();
    }, []);

    const rankChartData = useMemo(() => {
        const byDate = new Map<string, { holder_name: string; value: number }[]>();
        shareholders.forEach((s) => {
            const list = byDate.get(s.date) ?? [];
            list.push({holder_name: s.holder_name, value: s.value});
            byDate.set(s.date, list);
        });

        const dates = Array.from(byDate.keys()).sort((a, b) => a.localeCompare(b));
        const maxRank = Math.max(0, ...Array.from(byDate.values()).map((list) => list.length));

        const rankValues: (number | null)[][] = Array.from({length: maxRank}, () => []);
        dates.forEach((date) => {
            const sorted = [...(byDate.get(date) ?? [])].sort((a, b) => b.value - a.value);
            for (let rank = 0; rank < maxRank; rank++) {
                rankValues[rank].push(sorted[rank] ? sorted[rank].value : null);
            }
        });

        return {dates, rankValues};
    }, [shareholders]);

    const canvasRef = useRef<HTMLCanvasElement | null>(null);
    const chartRef = useRef<Chart | null>(null);

    useEffect(() => {
        if (!canvasRef.current || rankChartData.dates.length === 0) return;

        const textColor = isDark ? "#f1f5f9" : "#0f172a";
        const gridColor = isDark ? "rgba(148,163,184,0.15)" : "rgba(100,116,139,0.15)";

        chartRef.current = new Chart(canvasRef.current, {
            type: "line",
            data: {
                labels: rankChartData.dates,
                datasets: rankChartData.rankValues.map((values, idx) => ({
                    label: rankLabel[lang](idx + 1),
                    data: values,
                    borderColor: RANK_COLORS[idx % RANK_COLORS.length],
                    backgroundColor: RANK_COLORS[idx % RANK_COLORS.length],
                    spanGaps: true,
                    tension: 0.3,
                    pointRadius: 3,
                })),
            },
            options: {
                responsive: true,
                maintainAspectRatio: false,
                scales: {
                    x: {ticks: {color: textColor}, grid: {color: gridColor}},
                    y: {
                        ticks: {color: textColor},
                        grid: {color: gridColor},
                        title: {display: true, text: stockLabels.stakePercent[lang], color: textColor},
                    },
                },
                plugins: {
                    legend: {display: false},
                },
            },
        });

        return () => {
            chartRef.current?.destroy();
            chartRef.current = null;
        };
    }, [rankChartData, isDark, lang]);

    const investorCanvasRef = useRef<HTMLCanvasElement | null>(null);
    const investorChartRef = useRef<Chart | null>(null);

    useEffect(() => {
        if (!investorCanvasRef.current || investors.length === 0) return;

        const textColor = isDark ? "#f1f5f9" : "#0f172a";
        const gridColor = isDark ? "rgba(148,163,184,0.15)" : "rgba(100,116,139,0.15)";

        investorChartRef.current = new Chart(investorCanvasRef.current, {
            type: "line",
            data: {
                labels: investors.map((i) => i.base_date),
                datasets: [
                    {
                        label: stockLabels.investorCount[lang],
                        data: investors.map((i) => i.investor_count),
                        borderColor: RANK_COLORS[0],
                        backgroundColor: RANK_COLORS[0],
                        yAxisID: "y",
                        spanGaps: true,
                        tension: 0.3,
                        pointRadius: 3,
                    },
                    {
                        label: stockLabels.avgPrice[lang],
                        data: investors.map((i) => i.avg_price),
                        borderColor: RANK_COLORS[1],
                        backgroundColor: RANK_COLORS[1],
                        yAxisID: "y1",
                        spanGaps: true,
                        tension: 0.3,
                        pointRadius: 3,
                    },
                ],
            },
            options: {
                responsive: true,
                maintainAspectRatio: false,
                scales: {
                    x: {ticks: {color: textColor}, grid: {color: gridColor}},
                    y: {
                        position: "left",
                        ticks: {color: textColor},
                        grid: {color: gridColor},
                        title: {display: true, text: stockLabels.investorCount[lang], color: textColor},
                    },
                    y1: {
                        position: "right",
                        ticks: {color: textColor},
                        grid: {drawOnChartArea: false},
                        title: {display: true, text: stockLabels.avgPrice[lang], color: textColor},
                    },
                },
                plugins: {
                    legend: {labels: {color: textColor}},
                },
            },
        });

        return () => {
            investorChartRef.current?.destroy();
            investorChartRef.current = null;
        };
    }, [investors, isDark, lang]);

    if (!stock) {
        return (
            <div className="min-h-screen flex flex-col bg-white dark:bg-slate-950">
                <Header/>
                <main className="flex-1 p-10 text-center text-slate-500 dark:text-slate-400">
                    <I18nText dict={stockLabels.notFound} lang={lang}/>
                </main>
                <Footer/>
            </div>
        );
    }

    return (
        <div className="min-h-screen flex flex-col bg-white dark:bg-slate-950 text-slate-900 dark:text-slate-100">
            <Header/>
            <main className="flex-1 mx-auto w-full max-w-4xl px-4 py-10 space-y-12">
                <header className="border-b border-slate-200 dark:border-slate-800 pb-8">
                    <div className="flex flex-wrap items-start justify-between gap-3">
                        <div className="flex items-baseline gap-3 flex-wrap">
                            <span className="px-2 py-0.5 rounded text-xs font-bold tracking-wider bg-blue-100 text-blue-600 dark:bg-blue-900/30">
                                {stock.market}
                            </span>
                            <h1 className="text-4xl font-extrabold tracking-tight">{stock.stock_name}</h1>
                            <span className="text-2xl text-slate-400 font-light">{stock.symbol}</span>
                            {stock.nps_holding && (
                                <span className="px-2 py-0.5 rounded text-xs font-bold tracking-wider bg-emerald-100 text-emerald-700 dark:bg-emerald-900/30 dark:text-emerald-400">
                                    <I18nText dict={stockLabels.npsHolding} lang={lang}/>
                                </span>
                            )}
                        </div>
                        <LangSwitcher lang={lang} onChange={setLang}/>
                    </div>
                </header>

                <section className="grid grid-cols-1 md:grid-cols-3 gap-6">
                    <div className="bg-slate-50 dark:bg-slate-900/50 p-6 rounded-2xl border border-slate-200 dark:border-slate-800">
                        <div className="flex justify-between items-start mb-2">
                            <p className="text-sm font-medium text-slate-500"><I18nText dict={stockLabels.recentPrice} lang={lang}/></p>
                            {stock.basis_date && (
                                <span className="text-[10px] font-mono text-slate-400 bg-slate-100 dark:bg-slate-800 px-1.5 py-0.5 rounded">
                                    <I18nText
                                        dict={{
                                            ko: asOfDate(stock.basis_date, "ko"),
                                            en: asOfDate(stock.basis_date, "en"),
                                            ja: asOfDate(stock.basis_date, "ja"),
                                            zh: asOfDate(stock.basis_date, "zh"),
                                        }}
                                        lang={lang}
                                    />
                                </span>
                            )}
                        </div>
                        <div className="flex items-baseline gap-1">
                            <span className="text-3xl font-bold">
                                {stock.recent_price != null ? stock.recent_price.toLocaleString() : <I18nText dict={stockLabels.none} lang={lang}/>}
                            </span>
                            {stock.recent_price != null && (
                                <span className="text-slate-400 text-sm font-medium">{getCurrency(stock.market, lang)}</span>
                            )}
                        </div>
                    </div>

                    <div className="bg-slate-50 dark:bg-slate-900/50 p-6 rounded-2xl border border-slate-200 dark:border-slate-800">
                        <p className="text-sm font-medium text-slate-500 mb-2"><I18nText dict={stockLabels.growthRate} lang={lang}/></p>
                        {stock.growth != null ? (
                            <div className={`text-3xl font-bold ${stock.growth > 0 ? "text-red-500" : stock.growth < 0 ? "text-blue-500" : ""}`}>
                                {stock.growth > 0 ? "▲" : stock.growth < 0 ? "▼" : ""} {Math.abs(stock.growth).toFixed(2)}%
                            </div>
                        ) : (
                            <div className="text-3xl font-bold text-slate-300 dark:text-slate-700 font-mono"><I18nText dict={stockLabels.none} lang={lang}/></div>
                        )}
                    </div>

                    <div className="bg-slate-50 dark:bg-slate-900/50 p-6 rounded-2xl border border-slate-200 dark:border-slate-800">
                        <p className="text-sm font-medium text-slate-500 mb-2"><I18nText dict={stockLabels.dividendPerShare} lang={lang}/></p>
                        {stock.dividend != null && stock.dividend > 0 ? (
                            <div className="flex items-baseline gap-1 text-emerald-600 dark:text-emerald-400">
                                <span className="text-3xl font-bold">{stock.dividend.toLocaleString()}</span>
                                <span className="text-sm font-medium">{getCurrency(stock.market, lang)}</span>
                            </div>
                        ) : (
                            <div className="text-3xl font-bold text-slate-300 dark:text-slate-700 font-mono"><I18nText dict={stockLabels.none} lang={lang}/></div>
                        )}
                    </div>
                </section>

                {stock.overview && (
                    <section className="space-y-4">
                        <h3 className="text-xl font-bold px-1"><I18nText dict={stockLabels.overview} lang={lang}/></h3>
                        <p className="rounded-2xl border border-slate-200 dark:border-slate-800 bg-slate-50 dark:bg-slate-900/50 p-6 text-sm leading-relaxed whitespace-pre-line text-slate-700 dark:text-slate-300">
                            {stock.overview}
                        </p>
                    </section>
                )}

                <section className="space-y-4">
                    <h3 className="text-xl font-bold px-1"><I18nText dict={stockLabels.shareholderTrend} lang={lang}/></h3>
                    {rankChartData.dates.length > 0 ? (
                        <div className="rounded-2xl border border-slate-200 dark:border-slate-800 p-4" style={{height: 320}}>
                            <canvas ref={canvasRef}/>
                        </div>
                    ) : (
                        <div className="py-10 text-center border-2 border-dashed border-slate-100 dark:border-slate-800 rounded-2xl text-slate-400 text-sm">
                            <I18nText dict={stockLabels.noChartData} lang={lang}/>
                        </div>
                    )}
                </section>

                <section className="space-y-4">
                    <h3 className="text-xl font-bold px-1"><I18nText dict={stockLabels.shareholderInfo} lang={lang}/></h3>
                    {shareholders.length > 0 ? (
                        <div className="overflow-hidden rounded-2xl border border-slate-200 dark:border-slate-800 shadow-sm">
                            <table className="w-full text-left text-sm border-collapse">
                                <thead className="bg-slate-50 dark:bg-slate-900/80 border-b border-slate-200 dark:border-slate-800 text-slate-500">
                                <tr>
                                    <th className="px-6 py-4 font-semibold text-center"><I18nText dict={stockLabels.baseDate} lang={lang}/></th>
                                    <th className="px-6 py-4 font-semibold text-center"><I18nText dict={stockLabels.shareholderName} lang={lang}/></th>
                                    <th className="px-6 py-4 font-semibold text-center"><I18nText dict={stockLabels.stake} lang={lang}/></th>
                                </tr>
                                </thead>
                                <tbody className="divide-y divide-slate-100 dark:divide-slate-800">
                                {shareholders.map((item) => (
                                    <tr key={item.id} className="hover:bg-slate-50/50 dark:hover:bg-slate-900/30 transition-colors">
                                        <td className="px-6 py-4 text-slate-500 font-mono text-xs">{item.date}</td>
                                        <td className="px-6 py-4 font-medium">{item.holder_name}</td>
                                        <td className="px-6 py-4 text-right font-bold text-slate-900 dark:text-slate-100">
                                            {item.value.toLocaleString()}
                                        </td>
                                    </tr>
                                ))}
                                </tbody>
                            </table>
                        </div>
                    ) : (
                        <div className="py-10 text-center border-2 border-dashed border-slate-100 dark:border-slate-800 rounded-2xl text-slate-400 text-sm">
                            <I18nText dict={stockLabels.noShareholderInfo} lang={lang}/>
                        </div>
                    )}
                </section>

                <section className="space-y-4">
                    <h3 className="text-xl font-bold px-1"><I18nText dict={stockLabels.investorTrend} lang={lang}/></h3>
                    {investors.length > 0 ? (
                        <div className="rounded-2xl border border-slate-200 dark:border-slate-800 p-4" style={{height: 320}}>
                            <canvas ref={investorCanvasRef}/>
                        </div>
                    ) : (
                        <div className="py-10 text-center border-2 border-dashed border-slate-100 dark:border-slate-800 rounded-2xl text-slate-400 text-sm">
                            <I18nText dict={stockLabels.noChartData} lang={lang}/>
                        </div>
                    )}
                </section>
            </main>
            <Ticker/>
            <Footer/>
        </div>
    );
};

export default StockDetailPage;

export const Head: HeadFC<DataProps> = ({data}) => (
    <title>{data.stockDetail ? `${data.stockDetail.stock_name} (${data.stockDetail.symbol})` : "종목 상세"}</title>
);
